// Prepends the required GENERATED header (CLAUDE.md §4) to every file Mitosis
// just wrote, since Mitosis itself doesn't add one.
import { readdirSync, readFileSync, writeFileSync, statSync } from "node:fs";
import { join, extname } from "node:path";

const GEN_DIRS = [join(import.meta.dirname, "../../gen/react/src"), join(import.meta.dirname, "../../gen/svelte/src")];

const HEADER_BY_EXT = {
  ".jsx": (name) => `// GENERATED by Mitosis from packages/ir/${name}.lite.tsx. Do not edit. Regenerate with: pnpm ir:build\n`,
  ".svelte": (name) => `<!-- GENERATED by Mitosis from packages/ir/${name}.lite.tsx. Do not edit. Regenerate with: pnpm ir:build -->\n`,
};

for (const dir of GEN_DIRS) {
  for (const file of readdirSync(dir)) {
    const path = join(dir, file);
    if (!statSync(path).isFile()) continue;
    const ext = extname(file);
    const makeHeader = HEADER_BY_EXT[ext];
    if (!makeHeader) continue;
    const name = file.slice(0, -ext.length);
    const header = makeHeader(name);
    const content = readFileSync(path, "utf8");
    if (content.startsWith(header.split("\n")[0])) continue; // already prepended
    writeFileSync(path, header + content);
  }
}
